INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind DHCP-Abfragen immer erfolgreich?', 2, '[{"text": "Nein", "correct": true, "because": "Server kann ausfallen"}, {"text": "Ja", "correct": false, "because": "Fehler möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der Client bei DHCP-Abfragen?', 3, '[{"text": "Sendet DHCPDISCOVER", "correct": true, "because": "Startet Adressanfrage"}, {"text": "Weist IPs zu", "correct": false, "because": "Server-Aufgabe"}, {"text": "Misst Latenz", "correct": false, "because": "Ping-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zu einer DHCP-Abfrage?', 5, '[{"text": "DHCPDISCOVER", "correct": true, "because": "Client sucht Server"}, {"text": "DHCPOFFER", "correct": true, "because": "Server bietet IP"}, {"text": "Echo Request", "correct": false, "because": "Ping-spezifisch"}, {"text": "DNS-Auflösung", "correct": false, "because": "Andere Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DHCPREQUEST bestätigt die IP. b) Server antwortet immer sofort.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Antwortzeit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei DHCP-Abfragen?', 4, '[{"text": "DHCPDISCOVER", "correct": false, "because": "Start der Abfrage"}, {"text": "DHCPACK", "correct": false, "because": "Bestätigt IP"}, {"text": "Webserver-Status", "correct": true, "because": "Nicht DHCP-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DHCP-Abfragen Multicast nutzen?', 2, '[{"text": "Ja", "correct": true, "because": "DHCPDISCOVER an FF02::1:2"}, {"text": "Nein", "correct": false, "because": "Multicast ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachricht sendet der Client zuerst?', 3, '[{"text": "DHCPDISCOVER", "correct": true, "because": "Sucht verfügbare Server"}, {"text": "DHCPREQUEST", "correct": false, "because": "Späterer Schritt"}, {"text": "DHCPACK", "correct": false, "because": "Server-Antwort"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Antworten kommen vom DHCP-Server?', 5, '[{"text": "DHCPOFFER", "correct": true, "because": "Bietet IP an"}, {"text": "DHCPACK", "correct": true, "because": "Bestätigt Zuweisung"}, {"text": "Echo Reply", "correct": false, "because": "Ping-spezifisch"}, {"text": "Neighbor Solicitation", "correct": false, "because": "NDP-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DHCPDISCOVER ist Multicast. b) Server antwortet mit Unicast. Stimmt das?', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Multicast-Abfrage, Unicast-Antwort"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DHCP-Abfragen?', 4, '[{"text": "DHCPDISCOVER", "correct": false, "because": "Startet Prozess"}, {"text": "DHCPOFFER", "correct": false, "because": "Server-Vorschlag"}, {"text": "HTTP-Anfrage", "correct": true, "because": "Nicht DHCP-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist DHCPREQUEST die erste Nachricht?', 2, '[{"text": "Nein", "correct": true, "because": "Folgt auf DHCPDISCOVER"}, {"text": "Ja", "correct": false, "because": "Erster Schritt ist DISCOVER"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Server-Antwort bestätigt die IP-Zuweisung?', 4, '[{"text": "DHCPACK", "correct": true, "because": "Schließt Zuweisung ab"}, {"text": "DHCPOFFER", "correct": false, "because": "Nur Angebot"}, {"text": "DHCPDISCOVER", "correct": false, "because": "Client-Anfrage"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DHCP-Abfragen immer lokal sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann über Relay gehen"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig lokal"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Analyse von DHCP-Abfragen?', 3, '[{"text": "DHCPDISCOVER", "correct": true, "because": "Startet den Prozess"}, {"text": "DNS-Einträge", "correct": false, "because": "Sekundär"}, {"text": "Latenzzeit", "correct": false, "because": "Ping-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DHCPOFFER kommt vom Server. b) Client sendet DHCPACK.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DHCPACK ist Server-Antwort"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten DHCP-Abfragen?', 5, '[{"text": "Automatische IP-Zuweisung", "correct": true, "because": "Vereinfacht Konfiguration"}, {"text": "Netzwerkflexibilität", "correct": true, "because": "Dynamische Adressen"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht enthalten"}, {"text": "Latenzmessung", "correct": false, "because": "Ping-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei DHCP-Abfragen unwichtig?', 3, '[{"text": "DHCPREQUEST", "correct": false, "because": "Bestätigt IP"}, {"text": "DHCPACK", "correct": false, "because": "Schließt ab"}, {"text": "Web-UI-Design", "correct": true, "because": "Nicht Netzwerk-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzt DHCP-Abfragen nur Unicast?', 3, '[{"text": "Nein", "correct": true, "because": "DISCOVER ist Multicast"}, {"text": "Ja", "correct": false, "because": "Kombination beider"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DHCP-Abfragen DNS setzen?', 2, '[{"text": "Ja", "correct": true, "because": "Option in DHCPOFFER"}, {"text": "Nein", "correct": false, "because": "Teil der Konfiguration"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachricht fordert eine IP vom Server an?', 4, '[{"text": "DHCPREQUEST", "correct": true, "because": "Akzeptiert Angebot"}, {"text": "DHCPDISCOVER", "correct": false, "because": "Sucht nur"}, {"text": "DHCPACK", "correct": false, "because": "Server-Bestätigung"}]');
